SELECT current_user AS executor,
       (SELECT rolsuper FROM pg_roles WHERE rolname=current_user) AS executor_is_superuser;
SELECT datname, pg_get_userbyid(datdba) AS db_owner FROM pg_database WHERE datname='smdb';
SELECT nspname, pg_get_userbyid(nspowner) AS schema_owner, nspacl::text AS acl_before
  FROM pg_namespace WHERE nspname='public';

SELECT p.proname, pg_get_userbyid(p.proowner) AS owner FROM pg_proc p
  JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='sm_data' ORDER BY 1;
SELECT t.tgname, t.tgrelid::regclass AS tbl, p.proname AS fn, t.tgenabled
  FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal ORDER BY 1;

SET ROLE sm_dp_owner;
CREATE TABLE sm_data.future_table(x int);
SELECT has_table_privilege('sm_dp_runtime','sm_data.future_table','SELECT') AS runtime_select,
       has_table_privilege('sm_dp_runtime','sm_data.future_table','INSERT') AS runtime_insert;
DROP TABLE sm_data.future_table;

