SELECT 'owner re-keyed placement rows='||count(*) FROM sm_data.placement_watermark WHERE placement_id='b3b3b3b3-3333-4333-8333-b3b3b3b3b3b3';
DELETE FROM sm_data.placement_watermark WHERE tenant_id='11111111-1111-4111-8111-111111111111' AND instance_id='a1a1a1a1-1111-4111-8111-a1a1a1a1a1a1';
SELECT 'owner deleted placement rows ok' AS r;
ROLLBACK;

SELECT idempotency_key, config_hash AS recorded, 'sha256:DIFFERENT' AS presented,
       (config_hash='sha256:DIFFERENT') AS retry_admissible
  FROM sm_data.apply_step_intent WHERE idempotency_key='idem-mat-0';

