UPDATE sm_data.apply_request SET resolution_note = NULL WHERE apply_id='c0000001-0000-4000-8000-000000000001';
SELECT state, resolution_note IS NULL AS note_null FROM sm_data.apply_request WHERE apply_id='c0000001-0000-4000-8000-000000000001';

SET ROLE sm_dp_owner;
BEGIN;
UPDATE sm_data.apply_step_intent SET config_hash='sha256:tampered' WHERE intent_id='e0000001-0000-4000-8000-000000000001';
SELECT 'owner updated intent rows='||count(*) FROM sm_data.apply_step_intent WHERE config_hash='sha256:tampered';
