SET ROLE sm_dp_owner;
BEGIN;
DELETE FROM sm_data.apply_attempt WHERE intent_id='e0000001-0000-4000-8000-000000000001';
DELETE FROM sm_data.apply_step_intent WHERE intent_id='e0000001-0000-4000-8000-000000000001';
SELECT 'owner deleted intent ok' AS r;
