SET ROLE sm_dp_owner;
BEGIN;
UPDATE sm_data.apply_request SET requested_by='op:forged' WHERE apply_id='c0000021-0000-4000-8000-000000000021';
SELECT 'owner rewrote requested_by rows='||count(*) FROM sm_data.apply_request WHERE requested_by='op:forged';
