BEGIN;
UPDATE sm_data.apply_request SET state='INDETERMINATE_RESOLVED', terminal_at=now(), resolved_by='op:res',
  resolution_outcome='applied', resolution_observed='{"stagedGeneration": 30, "replicas": [{"ref": "r0", "restarted": true, "observedHash": null}]}'::jsonb
 WHERE apply_id='70000001-0000-4000-8000-000000000001';
UPDATE sm_data.apply_scope SET instance_watermark=30 WHERE tenant_id='44444444-4444-4444-8444-444444444444' AND instance_id='a2a2a2a2-2222-4222-8222-a2a2a2a2a2a2';
SELECT g AS "candidate_G", s.instance_watermark AS bar,
       CASE WHEN g <= s.instance_watermark THEN 'REFUSE' ELSE 'ADMIT' END AS verdict
  FROM sm_data.apply_scope s, (VALUES (29::bigint),(30::bigint),(31::bigint)) v(g)
 WHERE s.tenant_id='44444444-4444-4444-8444-444444444444' AND s.instance_id='a2a2a2a2-2222-4222-8222-a2a2a2a2a2a2' ORDER BY g;
COMMIT;

SELECT state, resolution_outcome, generation FROM sm_data.apply_request WHERE apply_id='70000001-0000-4000-8000-000000000001';
SELECT g AS "candidate_G", s.instance_watermark AS bar,
       CASE WHEN g <= s.instance_watermark THEN 'REFUSE' ELSE 'ADMIT' END AS verdict
  FROM sm_data.apply_scope s, (VALUES (29::bigint),(30::bigint),(31::bigint)) v(g)
 WHERE s.tenant_id='44444444-4444-4444-8444-444444444444' AND s.instance_id='a2a2a2a2-2222-4222-8222-a2a2a2a2a2a2' ORDER BY g;

